/** 登录弹窗/页面的完整样式字符串 */
export declare const loginStyles = "\n/* ---- \u906E\u7F69\u5C42 ---- */\n.auth-sdk-overlay {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: rgba(0, 0, 0, 0.5);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 2147483647;\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n}\n\n/* ---- \u5168\u5C4F\u6A21\u5F0F ---- */\n.auth-sdk-overlay.fullscreen {\n  background: #f5f7fa;\n  align-items: flex-start;\n  padding-top: 80px;\n}\n\n/* ---- \u767B\u5F55\u5361\u7247 ---- */\n.auth-sdk-card {\n  background: #fff;\n  border-radius: 12px;\n  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);\n  padding: 40px 36px 32px;\n  width: 380px;\n  max-width: 90vw;\n  box-sizing: border-box;\n}\n\n.fullscreen .auth-sdk-card {\n  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);\n}\n\n/* ---- \u6807\u9898 ---- */\n.auth-sdk-title {\n  text-align: center;\n  margin: 0 0 8px 0;\n  font-size: 22px;\n  font-weight: 600;\n  color: #1a1a1a;\n}\n\n.auth-sdk-subtitle {\n  text-align: center;\n  margin: 0 0 28px 0;\n  font-size: 14px;\n  color: #8c8c8c;\n}\n\n/* ---- \u8868\u5355\u7EC4 ---- */\n.auth-sdk-form-group {\n  margin-bottom: 20px;\n}\n\n.auth-sdk-label {\n  display: block;\n  margin-bottom: 6px;\n  font-size: 14px;\n  font-weight: 500;\n  color: #333;\n}\n\n.auth-sdk-input {\n  width: 100%;\n  height: 40px;\n  padding: 0 12px;\n  border: 1px solid #d9d9d9;\n  border-radius: 6px;\n  font-size: 14px;\n  color: #333;\n  outline: none;\n  box-sizing: border-box;\n  transition: border-color 0.2s, box-shadow 0.2s;\n}\n\n.auth-sdk-input:focus {\n  border-color: #1677ff;\n  box-shadow: 0 0 0 2px rgba(22, 119, 255, 0.15);\n}\n\n.auth-sdk-input::placeholder {\n  color: #bfbfbf;\n}\n\n/* ---- \u5BC6\u7801\u8F93\u5165\u6846\u5BB9\u5668 ---- */\n.auth-sdk-password-wrapper {\n  position: relative;\n}\n\n.auth-sdk-toggle-btn {\n  position: absolute;\n  right: 8px;\n  top: 50%;\n  transform: translateY(-50%);\n  background: none;\n  border: none;\n  cursor: pointer;\n  color: #8c8c8c;\n  font-size: 13px;\n  padding: 4px 6px;\n}\n\n.auth-sdk-toggle-btn:hover {\n  color: #1677ff;\n}\n\n/* ---- \u9519\u8BEF\u63D0\u793A ---- */\n.auth-sdk-error {\n  margin-bottom: 16px;\n  padding: 8px 12px;\n  background: #fff2f0;\n  border: 1px solid #ffccc7;\n  border-radius: 6px;\n  color: #ff4d4f;\n  font-size: 13px;\n  line-height: 1.4;\n  display: none;\n}\n\n.auth-sdk-error.visible {\n  display: block;\n}\n\n/* ---- \u63D0\u4EA4\u6309\u94AE ---- */\n.auth-sdk-submit-btn {\n  width: 100%;\n  height: 42px;\n  background: #1677ff;\n  color: #fff;\n  border: none;\n  border-radius: 6px;\n  font-size: 15px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: background 0.2s;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n}\n\n.auth-sdk-submit-btn:hover {\n  background: #4096ff;\n}\n\n.auth-sdk-submit-btn:active {\n  background: #0958d9;\n}\n\n.auth-sdk-submit-btn:disabled {\n  background: #a0c4ff;\n  cursor: not-allowed;\n}\n\n/* ---- \u52A0\u8F7D\u4E2D\u72B6\u6001 ---- */\n.auth-sdk-spinner {\n  display: inline-block;\n  width: 16px;\n  height: 16px;\n  border: 2px solid rgba(255, 255, 255, 0.3);\n  border-top-color: #fff;\n  border-radius: 50%;\n  animation: auth-sdk-spin 0.6s linear infinite;\n}\n\n@keyframes auth-sdk-spin {\n  to { transform: rotate(360deg); }\n}\n";
